import pytest
from app.urgency import find_urgent, user_part

@pytest.mark.parametrize("text", [
"сильна кровотеча з вени", "кров не зупиняється", "раптово набрякла нога", "нога раптово побіліла", "стопа посиніла", "нога похолодніла", "стопа оніміла", "різкий нестерпний біль", "болить у грудях і набрякла нога", "задишка і болить нога", "кашель з кров'ю та набряк ноги", "втратив свідомість", "різка слабкість", "гострий біль у литці", "литка болить гостро", "набрякла одна нога", "одна нога набрякає", "набряк наростає кілька днів", "почервоніння вздовж вени", "жар по вені", "ущільнення вздовж вени", "рана з гноєм", "виразка почервоніла", "кровотеча була, але зупинилась", "та нічого страшного, просто нога раптом побіліла", "нічого, але стопа холодна і заніміла", "каже що не болить, та литка гостро заболіла", "одна нога стала синя", "рана гноїться", "сильний біль у грудях", "важко дихати", "непритомнію", "раптове посиніння стопи", "кровить варикозний вузол", "нога різко опухла"] )
def test_urgent_positive(text):
    assert find_urgent(text)

@pytest.mark.parametrize("text", ["варикоз, хочу записатися на консультацію", "зірочки на ногах", "важкість у ногах ввечері", "хочу консультацію флеболога", "вени видно давно", "іноді втомлюються ноги", "підберіть трикотаж", "хочу зробити УЗД", "запишіть на наступний тиждень", "легкий свербіж шкіри", "обидві ноги втомлені після прогулянки", "трохи набрякають щиколотки в спеку", "нема болю, хочу консультацію", "дзвоню щодо ціни", "чи є флеболог у Львові", "хочу лазерне лікування", "боліла нога торік", "судинні зірочки", "важкість проходить після відпочинку", "підкажіть адресу"] )
def test_urgent_negative(text):
    assert find_urgent(text) == []

def test_none_empty():
    assert find_urgent(None) == [] and find_urgent("  ") == []

def test_user_part():
    assert user_part("Assistant: Hi\nUser: перший\nрядок\nAssistant: ok\nCustomer: другий") == "перший\nрядок\nдругий"
    assert user_part("просто текст") == "просто текст"
